function LogoTapeItem({ logo, decorative }: { logo: Logo; decorative?: boolean }) {
  const shared = 'inline-flex items-center mx-7 shrink-0 opacity-60 hover:opacity-100 transition-opacity duration-200'
  return (
    <a
      href={logo.href}
      target="_blank"
      rel="noopener noreferrer"
      className={shared}
      style={{ color: 'var(--tw-text-primary)' }}
      aria-label={decorative ? undefined : `${logo.name} — opens in a new tab`}
      title={decorative ? undefined : logo.name}
      aria-hidden={decorative || undefined}
      tabIndex={decorative ? -1 : undefined}
    >
      {logo.path ? (
        <svg
          role="img"
          aria-label={decorative ? undefined : logo.name}
          aria-hidden={decorative || undefined}
          focusable="false"
          viewBox={logo.viewBox}
          fill="currentColor"
          style={{ height: 26, width: 'auto', display: 'block' }}
        >
          <title>{logo.name}</title>
          <path d={logo.path} />
        </svg>
      ) : (
        <span
          style={{
            fontWeight: 600,
            fontSize: 19,
            letterSpacing: '-0.02em',
            whiteSpace: 'nowrap',
          }}
        >
          {logo.name}
        </span>
      )}
    </a>
  )
}

export default function LogoTape() {
  return (
    <section
      aria-label="Technologies the build factory runs on"
      className="w-full overflow-hidden"
      style={{
        background: 'transparent',
        borderTop: '0.5px solid var(--tw-border-primary)',
        borderBottom: '0.5px solid var(--tw-border-primary)',
      }}
    >
      <div className="tape-track flex w-max items-center py-6">
        {LOGOS.map((logo) => (
          <LogoTapeItem key={`a-${logo.name}`} logo={logo} />
        ))}
        {LOGOS.map((logo) => (
          <LogoTapeItem key={`b-${logo.name}`} logo={logo} decorative />
        ))}
      </div>
    </section>
  )
}
